mod io;use quantum_ecc::circuit::{Op,OperationType as K};use sha3::{Digest,Sha3_256};
fn fields(o:&Op)->[u64;7]{[o.kind as u64,o.q_control2.0,o.q_control1.0,o.q_target.0,o.c_target.0,o.c_condition.0,o.r_target.0]}
fn hash(ops:&[Op])->String{let mut h=Sha3_256::new();for o in ops{for v in fields(o){h.update(v.to_le_bytes());}}format!("{:x}",h.finalize())}
fn main(){let a:Vec<_>=std::env::args().collect();assert_eq!(a.len(),4);let old=io::load_ops(&a[1]);let new=io::load_ops(&a[2]);assert_eq!(old.len(),11682054);assert_eq!(old.len(),new.len());assert_eq!(hash(&old),"3000fc9119ca08944ea9f087f1f69d42a149ede69ea6221b8a60e2f23929171b");assert_eq!(hash(&new),"f09ef07a02790dfc2c80293b0d45f25dae824db4a6a024ad52289ca5889c9a5e");let diff:Vec<_>=old.iter().zip(&new).enumerate().filter(|(_, (x,y))|x!=y).collect();assert_eq!(diff.len(),1);let(i, (before,after))=diff[0];assert_eq!(before.kind,K::CCX);assert_eq!(after.kind,K::CX);assert_eq!(after.q_control2.0,u64::MAX);assert!([before.q_control1,before.q_control2].contains(&after.q_control1));assert_eq!(before.q_target,after.q_target);assert_eq!(before.c_target,after.c_target);assert_eq!(before.c_condition,after.c_condition);assert_eq!(before.r_target,after.r_target);let report=serde_json::json!({"status":"EXACT_SINGLE_RECORD_CHANGE_BOUND_TO_QUALIFIED_SEMANTIC_PROOF","record_index":i,"before":fields(before),"after":fields(after),"input_records_sha3":hash(&old),"output_records_sha3":hash(&new),"operation_count":old.len(),"scope":"Read-only source binding. Exact native12-qualified global-prefix semantic pass has precisely this one CCXtoCX difference; no input/gate/nonce/benchmark/score."});std::fs::write(&a[3],serde_json::to_string_pretty(&report).unwrap()+"\n").unwrap();println!("{report}");}
